patch:
diff --git a/lib/netrc.c b/lib/netrc.c
index e787a6f..af9ac13 100644
--- a/lib/netrc.c
+++ b/lib/netrc.c
@@ -315,7 +315,7 @@ out:
     if(!password)
       retcode = 1; /* out of memory */
   }
-  if(!retcode) {
+  if(!retcode && (!specific_login || our_login)) {
     /* success */
     if(!specific_login)
       *loginp = login;
@@ -326,6 +326,7 @@ out:
     if(!specific_login)
       free(login);
     free(password);
+    retcode = NETRC_FILE_MISSING; /* no matching login found */
   }

   return retcode;
